import { Component, Element, Prop, Watch } from "@stencil/core";
import resolveElementFromElementOrString from "./portal.util";

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
  tag: "hbr-portal",
  styleUrl: "portal.scss",
  shadow: true,
})
export class HbrPortal {
  @Element() el: HTMLElement;

  @Prop() target: HTMLElement | string = "body";

  private targetRef: HTMLElement;

  movedChildren = [];

  @Watch("target")
  handletargetChange() {
    this.targetRef = resolveElementFromElementOrString(this.target, true);
  }

  connectedCallback() {
    this.handletargetChange = this.handletargetChange.bind(this);
  }

  componentWillLoad() {
    this.handletargetChange();
  }

  componentDidLoad() {
    if (this.targetRef) {
      this.moveChildren();
    }
  }

  disconnectedCallback() {
    if (this.el && this.targetRef) {
      this.moveChildrenBack();
    }
  }

  moveChildren() {
    while (this.el.childNodes.length > 0) {
      const child = this.el.firstChild;
      this.targetRef.appendChild(this.el.firstChild);
      this.movedChildren.push(child);
    }
  }

  moveChildrenBack() {
    while (this.movedChildren.length > 0) {
      this.el.appendChild(this.movedChildren.pop());
    }
  }

  render() {
    return null;
  }
}
